## Why This Is Asked
Tests ability to design extensible systems and evaluate trade-offs between different eviction strategies.

## Key Concepts
- Strategy pattern for interchangeable algorithms
- Registry pattern for runtime extensibility
- Open/Closed principle and dependency injection
- Time/space complexity trade-offs for cache eviction

## Code Example
```typescript
interface EvictionPolicy<K, V> {
  evict(cache: Map<K, V>, accessLog: Map<K, number>): K;
  touch(key: K): void;
}

class LRUPolicy<K, V> implements EvictionPolicy<K, V> {
  private accessOrder: Map<K, number> = new Map();
  private timestamp = 0;

  evict(cache: Map<K, V>, accessLog: Map<K, number>): K {
    let oldestKey: K | null = null;
    let oldestTime = Infinity;

    for (const [key] of cache) {
      const time = this.accessOrder.get(key) ?? 0;
      if (time < oldestTime) {
        oldestTime = time;
        oldestKey = key;
      }
    }

    return oldestKey!;
  }

  touch(key: K): void {
    this.accessOrder.set(key, ++this.timestamp);
  }
}

class LFUPolicy<K, V> implements EvictionPolicy<K, V> {
  private frequencies: Map<K, number> = new Map();

  evict(cache: Map<K, V>, accessLog: Map<K, number>): K {
    let leastUsedKey: K | null = null;
    let lowestFreq = Infinity;

    for (const [key] of cache) {
      const freq = this.frequencies.get(key) ?? 0;
      if (freq < lowestFreq) {
        lowestFreq = freq;
        leastUsedKey = key;
      }
    }

    return leastUsedKey!;
  }

  touch(key: K): void {
    const current = this.frequencies.get(key) ?? 0;
    this.frequencies.set(key, current + 1);
  }
}

class TTLPolicy<K, V> implements EvictionPolicy<K, V> {
  private timestamps: Map<K, number> = new Map();
  private readonly ttlMs: number;

  constructor(ttlMs: number) {
    this.ttlMs = ttlMs;
  }

  evict(cache: Map<K, V>, accessLog: Map<K, number>): K {
    const now = Date.now();

    for (const [key, timestamp] of this.timestamps) {
      if (now - timestamp > this.ttlMs) {
        return key;
      }
    }

    const [firstKey] = cache.keys();
    return firstKey;
  }

  touch(key: K): void {
    this.timestamps.set(key, Date.now());
  }
}

class PolicyRegistry<K, V> {
  private policies = new Map<string, () => EvictionPolicy<K, V>>();

  register(name: string, factory: () => EvictionPolicy<K, V>): void {
    this.policies.set(name, factory);
  }

  create(name: string): EvictionPolicy<K, V> {
    const factory = this.policies.get(name);
    if (!factory) {
      throw new Error(`Unknown eviction policy: ${name}`);
    }
    return factory();
  }
}

class InMemoryCache<K, V> {
  private cache = new Map<K, V>();
  private policy: EvictionPolicy<K, V>;
  private maxSize: number;

  constructor(policy: EvictionPolicy<K, V>, maxSize: number = 100) {
    this.policy = policy;
    this.maxSize = maxSize;
  }

  get(key: K): V | undefined {
    const value = this.cache.get(key);
    if (value !== undefined) {
      this.policy.touch(key);
    }
    return value;
  }

  set(key: K, value: V): void {
    if (!this.cache.has(key) && this.cache.size >= this.maxSize) {
      const evictKey = this.policy.evict(this.cache, new Map());
      this.cache.delete(evictKey);
    }

    this.cache.set(key, value);
    this.policy.touch(key);
  }
}

const registry = new PolicyRegistry<string, any>();
registry.register('lru', () => new LRUPolicy<string, any>());
registry.register('lfu', () => new LFUPolicy<string, any>());
registry.register('ttl', () => new TTLPolicy<string, any>(5000));

const cache = new InMemoryCache(registry.create('lru'), 10);
```

## Why This Is Asked
This question assesses the ability to design extensible CLI architectures with runtime plugin support and graceful user experience.

### Key Concepts
- **Command pattern**: Encapsulates operations as first-class objects
- **Registry**: Enables dynamic command registration and lookup
- **Alias support**: Handles naming conflicts and provides convenient shortcuts
- **Auto-generated help**: Constructed from command metadata
- **Graceful failure**: Provides helpful error messages for unrecognized commands

### Code Example
```typescript
interface CommandContext {
  args: Record<string, unknown>;
  stdin: NodeJS.ReadableStream;
  stdout: NodeJS.WritableStream;
  stderr: NodeJS.WritableStream;
}

interface CommandDefinition {
  name: string;
  aliases: string[];
  description: string;
  parse(args: string[]): Record<string, unknown>;
  execute(ctx: CommandContext): Promise<void> | void;
}

class CommandRegistry {
  private commands = new Map<string, CommandDefinition>();

  register(cmd: CommandDefinition): void {
    this.commands.set(cmd.name, cmd);
    cmd.aliases.forEach(alias => this.commands.set(alias, cmd));
  }

  resolve(name: string): CommandDefinition | undefined {
    return this.commands.get(name);
  }

  getCommands(): CommandDefinition[] {
    return [...new Set(this.commands.values())];
  }

  generateHelp(): string {
    const commands = this.getCommands();
    const longestName = Math.max(...commands.map(c => c.name.length));
    return [
      'Usage: cli <command> [options]',
      '',
      'Commands:',
      ...commands.map(c => `  ${c.name.padEnd(longestName)}  ${c.description}`),
    ].join('\n');
  }
}

async function main(argv: string[]) {
  const [cmdName, ...args] = argv.slice(2);
  const registry = new CommandRegistry();

  // Register commands
  registry.register({
    name: 'greet',
    aliases: ['g'],
    description: 'Greet a user',
    parse(args) {
      const name = args[0] || 'World';
      return { name };
    },
    execute({ args, stdout }) {
      stdout.write(`Hello, ${args.name}!\n`);
    },
  });

  if (!cmdName) {
    console.log(registry.generateHelp());
    process.exit(0);
  }

  const cmd = registry.resolve(cmdName);
  if (!cmd) {
    console.error(`Error: Unknown command '${cmdName}'`);
    console.error(registry.generateHelp());
    process.exit(1);
  }

  const parsedArgs = cmd.parse(args);
  cmd.execute({
    args: parsedArgs,
    stdin: process.stdin,
    stdout: process.stdout,
    stderr: process.stderr,
  });
}

main(process.argv);
```

